  function openCoolingStart(id){const p=state.foodProducts.find(x=>x.id===id);if(!p)return;const existing=coolingToday().find(x=>x.status==='active'&&x.productId===id);if(existing){toast(`${p.name} is already cooling`);openCoolingRecheck(existing.id);return}coolingProductId=id;currentCoolingId='';coolingWheelMode='start';coolingManualField='start';coolingWheelAccumulator=0;$('#coolingEntryTitle').textContent=p.name;$('#coolingEntryEyebrow').textContent='Start live cooling';$('#coolingEntryRule').textContent=`From ${p.coolingFrom}°C to ≤${p.coolingTo}°C in ${p.coolingMinutes} min`;$('#coolingEntryNote').value='';$('#coolingStartFields').hidden=true;$('#coolingConfirm').textContent='Confirm';$('#coolingConfirm').hidden=false;$('#coolingFinish').hidden=true;setCoolingWheel(Math.max(Number(p.coolingFrom||63),63));showPage('cooling-entry')}
  function startCooling(){const p=state.foodProducts.find(x=>x.id===coolingProductId);if(!p)return;const now=new Date();coolingToday().push({id:`cooling-${Date.now()}`,productId:p.id,productName:p.name,status:'active',startTemperature:coolingTemp,lastTemperature:coolingTemp,startedAt:now.toISOString(),note:$('#coolingEntryNote').value.trim(),limits:{coolingFrom:p.coolingFrom,coolingTo:p.coolingTo,coolingMinutes:p.coolingMinutes}});addAudit('cooling','started',p.id,{temperature:coolingTemp,at:now.toISOString()});save();toast('Cooling started');renderCoolingDashboard();showPage('cooling-dashboard')}
  function openCoolingRecheck(id){const r=coolingToday().find(x=>x.id===id);if(!r)return;currentCoolingId=id;coolingWheelMode='recheck';$('#coolingEntryTitle').textContent=r.productName;$('#coolingEntryEyebrow').textContent='Cooling recheck';$('#coolingEntryRule').textContent=`Target ≤${r.limits.coolingTo}°C in ${r.limits.coolingMinutes} min`;$('#coolingEntryNote').value='';$('#coolingStartFields').hidden=true;$('#coolingConfirm').hidden=true;$('#coolingFinish').hidden=false;setCoolingWheel(3);showPage('cooling-entry')}
  function saveCoolingRecheck(forceComplete=false){const r=coolingToday().find(x=>x.id===currentCoolingId);if(!r)return;const now=new Date(),elapsed=Math.max(0,Math.round((now-new Date(r.startedAt))/60000));r.lastTemperature=coolingTemp;r.rechecks??=[];r.rechecks.push({temperature:coolingTemp,at:now.toISOString()});const reachedTarget=coolingTemp<=r.limits.coolingTo;if(forceComplete||reachedTarget){r.status='complete';r.finalTemperature=coolingTemp;r.completedAt=now.toISOString();r.durationMinutes=elapsed;r.pass=reachedTarget&&elapsed<=r.limits.coolingMinutes;if(!r.pass){state.issues[todayKey()]??={};state.issues[todayKey()][`cooling-${r.id}`]={source:'cooling',title:`${r.productName} cooling limit failed`,status:'open',value:coolingTemp,action:'cooling-limit-failed',createdAt:now.toISOString()}}}else if(elapsed>r.limits.coolingMinutes){r.overdue=true;r.pass=false;state.issues[todayKey()]??={};state.issues[todayKey()][`cooling-${r.id}`]={source:'cooling',title:`${r.productName} cooling overdue`,status:'open',value:coolingTemp,action:'cooling-overdue',createdAt:now.toISOString()}}addAudit('cooling','completed',r.productId,{temperature:coolingTemp,elapsed});save();toast(r.pass?'Cooling completed':'Cooling completed — action required');renderCoolingDashboard();showPage('cooling-dashboard')}
  function localInputValue(d=new Date()){const z=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${z(d.getMonth()+1)}-${z(d.getDate())}T${z(d.getHours())}:${z(d.getMinutes())}`}
  function openCoolingManual(id){
    const p=state.foodProducts.find(x=>x.id===id);if(!p)return;
    coolingProductId=id;coolingWheelMode='manual';
    coolingManualStartTemp=Math.max(-20,Math.min(120,Math.round(Number(p.coolingFrom||63)*2)/2));
    coolingManualFinalTemp=3;coolingManualField='start';
    $('#coolingEntryTitle').textContent=p.name;
    $('#coolingEntryEyebrow').textContent='Paper cooling report';
    $('#coolingEntryRule').textContent=`Adjust start and final temperatures · target ≤${p.coolingTo}°C in ${p.coolingMinutes} min`;
    $('#coolingEntryNote').value='';$('#coolingStartFields').hidden=false;
    const end=new Date(),start=new Date(end.getTime()-Math.min(90,p.coolingMinutes)*60000);
    $('#coolingStartedAt').value=localInputValue(start);$('#coolingCompletedAt').value=localInputValue(end);
    $('#coolingConfirm').textContent='Save Cooling Report';$('#coolingFinish').hidden=true;$('#coolingConfirm').hidden=false;
    renderCoolingManualTemperatureTabs();setCoolingWheel(coolingManualStartTemp);showPage('cooling-entry');
  }
  function saveManualCooling(){
    const p=state.foodProducts.find(x=>x.id===coolingProductId);if(!p)return;
    const started=new Date($('#coolingStartedAt').value),completed=new Date($('#coolingCompletedAt').value);
    if(!started.getTime()||!completed.getTime()||completed<=started)return toast('Check the start and completion times');
    const startTemp=coolingManualStartTemp,finalTemp=coolingManualFinalTemp;
    const duration=Math.round((completed-started)/60000),pass=finalTemp<=p.coolingTo&&duration<=p.coolingMinutes;
    const record={id:`cooling-${Date.now()}`,productId:p.id,productName:p.name,status:'complete',manual:true,startTemperature:startTemp,finalTemperature:finalTemp,lastTemperature:finalTemp,startedAt:started.toISOString(),completedAt:completed.toISOString(),durationMinutes:duration,pass,note:$('#coolingEntryNote').value.trim(),limits:{coolingFrom:p.coolingFrom,coolingTo:p.coolingTo,coolingMinutes:p.coolingMinutes}};
    coolingToday().push(record);addAudit('cooling','manual-report',p.id,record);
    if(!pass){state.issues[todayKey()]??={};state.issues[todayKey()][`cooling-${record.id}`]={source:'cooling',title:`${p.name} cooling report`,status:'open',value:finalTemp,action:'cooling-limit-failed',createdAt:record.completedAt}}
    save();toast(pass?'Cooling report saved':'Cooling action required');renderCoolingDashboard();showPage('cooling-dashboard');
  }
  function renderCoolingReports(){const rows=coolingToday().filter(r=>r.status==='complete').sort((a,b)=>new Date(b.completedAt)-new Date(a.completedAt));$('#coolingReportsBadge').textContent=`${rows.length} reports`;$('#coolingReportsList').innerHTML=rows.slice(0,8).map(r=>`<button class="production-record-row ${r.pass?'pass':'fail'}" data-cooling-report="${r.id}"><span class="production-record-mark">${r.pass?'✓':'!'}</span><span><strong>${escapeHtml(r.productName)}</strong><small>${new Date(r.completedAt).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})} · ${r.finalTemperature.toFixed(1)}°C · ${r.durationMinutes} min</small></span><em>${r.pass?'PASS':'ACTION'}</em></button>`).join('')||'<div class="production-records-empty"><div><span>❄</span><h2>No cooling reports yet</h2></div></div>';$$('[data-cooling-report]').forEach(b=>b.onclick=()=>openCoolingReport(b.dataset.coolingReport))}
  function openCoolingReport(id){const r=coolingToday().find(x=>x.id===id);if(!r)return;$('#coolingReportProduct').textContent=r.productName;$('#coolingReportStatus').textContent=r.pass?'PASS':'ACTION';$('#coolingReportStatus').className=`badge ${r.pass?'report-pass':'report-fail'}`;$('#coolingReportStart').textContent=`${r.startTemperature.toFixed(1)}°C`;$('#coolingReportFinal').textContent=`${r.finalTemperature.toFixed(1)}°C`;$('#coolingReportDuration').textContent=`${r.durationMinutes} min`;$('#coolingReportTimes').textContent=`${new Date(r.startedAt).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})} – ${new Date(r.completedAt).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}`;$('#coolingReportRule').textContent=`≤${r.limits.coolingTo}°C within ${r.limits.coolingMinutes} min`;$('#coolingReportNote').textContent=r.note||'No note';showPage('cooling-report')}

  $('#coolingBack').onclick=()=>showPage('kitchen'); $('#startCoolingButton').onclick=()=>openCoolingProductPicker('live'); $('#addCoolingReportButton').onclick=()=>openCoolingProductPicker('manual'); $('#coolingTodayBadge').onclick=()=>{renderCoolingReports();showPage('cooling-reports')}; $('#coolingProductsBack').onclick=()=>{renderCoolingDashboard();showPage('cooling-dashboard')}; $('#coolingProductSearch').oninput=renderCoolingProducts; $('#coolingEntryBack').onclick=()=>{renderCoolingDashboard();showPage('cooling-dashboard')}; $('#coolingWheelUp').onclick=()=>setCoolingWheel(coolingTemp+.5); $('#coolingWheelDown').onclick=()=>setCoolingWheel(coolingTemp-.5); $('#coolingManualStartTab').onclick=()=>selectCoolingManualTemperature('start'); $('#coolingManualFinalTab').onclick=()=>selectCoolingManualTemperature('final'); const coolingWheel=$('#coolingWheel'); coolingWheel.addEventListener('touchstart',e=>{coolingWheelLastY=e.touches[0].clientY;coolingWheelAccumulator=0},{passive:true}); coolingWheel.addEventListener('touchmove',e=>{const y=e.touches[0].clientY;const dy=coolingWheelLastY-y;coolingWheelLastY=y;coolingWheelAccumulator+=dy;const pixelsPerStep=8;while(Math.abs(coolingWheelAccumulator)>=pixelsPerStep){const direction=coolingWheelAccumulator>0?1:-1;setCoolingWheel(coolingTemp+direction*.5);coolingWheelAccumulator-=direction*pixelsPerStep;}},{passive:true}); coolingWheel.addEventListener('touchend',()=>{coolingWheelAccumulator=0},{passive:true}); $('#coolingConfirm').onclick=()=>coolingWheelMode==='start'?startCooling():saveManualCooling(); $('#coolingFinish').onclick=()=>saveCoolingRecheck(true); $('#coolingReportsBack').onclick=()=>{renderCoolingDashboard();showPage('cooling-dashboard')}; $('#coolingReportBack').onclick=()=>{renderCoolingReports();showPage('cooling-reports')};
  $('[data-production-back]').onclick=()=>showPage('kitchen'); $('[data-production-list]').onclick=()=>{renderProductionList();showPage('production-list')}; $('#productionRecordCount').onclick=openProductionRecords; $('#productionRecordsBack').onclick=()=>{renderProductionList();showPage('production-list')}; $('#productionReportBack').onclick=openProductionRecords; $('#productionSearch').oninput=renderProductionList; $('#clearProductionSearch').onclick=()=>{$('#productionSearch').value='';renderProductionList();$('#productionSearch').focus()}; $('#productionTempUp').onclick=()=>adjustProduction(.5); $('#productionTempDown').onclick=()=>adjustProduction(-.5); $('#confirmProduction').onclick=confirmProductionRecord; $('#productionHoldingStartedAt').onchange=updateHoldingDurationPreview; $('#productionRecordedAtInput').onchange=updateHoldingDurationPreview;
  const productionWheel=$('#productionWheel');
  const beginProductionWheel=y=>{productionWheelLastY=y;productionWheelAccumulator=0};
  const moveProductionWheel=y=>{const dy=productionWheelLastY-y;productionWheelLastY=y;productionWheelAccumulator+=dy;const pixelsPerStep=8;while(Math.abs(productionWheelAccumulator)>=pixelsPerStep){const direction=productionWheelAccumulator>0?1:-1;adjustProduction(direction*.5);productionWheelAccumulator-=direction*pixelsPerStep;}};
  productionWheel.addEventListener('touchstart',e=>beginProductionWheel(e.touches[0].clientY),{passive:true});
  productionWheel.addEventListener('touchmove',e=>moveProductionWheel(e.touches[0].clientY),{passive:true});
  productionWheel.addEventListener('touchend',()=>productionWheelAccumulator=0,{passive:true});
  let productionPointerActive=false;
  productionWheel.addEventListener('pointerdown',e=>{productionPointerActive=true;productionWheel.setPointerCapture?.(e.pointerId);beginProductionWheel(e.clientY)});
  productionWheel.addEventListener('pointermove',e=>{if(productionPointerActive&&e.pointerType!=='touch')moveProductionWheel(e.clientY)});
  productionWheel.addEventListener('pointerup',()=>{productionPointerActive=false;productionWheelAccumulator=0});
  $$('[data-cooking-action]').forEach(b=>b.onclick=()=>{selectedCookingAction=b.dataset.cookingAction;$$('[data-cooking-action]').forEach(x=>x.classList.toggle('selected',x===b));$('#saveCookingAction').disabled=false}); $('#cancelCookingAction').onclick=()=>closeModal($('#cookingActionModal')); $('#saveCookingAction').onclick=()=>{if(!selectedCookingAction)return;const action={action:selectedCookingAction,note:$('#cookingActionNote').value.trim()};closeModal($('#cookingActionModal'));makeProductionRecord(action)};
  function renderAll(){syncCleaningIssues();renderDeliveryList();renderModules('kitchen');renderModules('service');renderTemperatureList();updateManager();if(activeManagementSection)renderManagementSection()}
  $('#todayLabel').textContent=new Intl.DateTimeFormat(undefined,{weekday:'long',day:'numeric',month:'long'}).format(new Date());renderAll();setMode(mode);
